/**
 * Hospitality and Event Management System (HEMS)
 * Real Gemini AI Requirement Generator Module
 * 
 * - Communicates with server-side endpoint POST /api/ai/analyze-event
 * - Gemini API key is securely handled on the backend server
 * - Parses validated structured JSON generated by Gemini 3 series model
 */

const AIRequirementGenerator = {
  /**
   * Calls the server-side Gemini AI service to analyze event specifications
   * and generate requirements, task breakdowns, and budget plans.
   * 
   * @param {Object} eventDetails
   * @returns {Promise<Array<Object>>} Formatted requirements list
   */
  async generateRequirements(eventDetails) {
    try {
      // Pass the entire event object so the backend has full context
      const payload = {
        ...eventDetails,
        guest_count: parseInt(eventDetails.guest_count, 10) || 0,
        budget: parseFloat(eventDetails.budget) || 0
      };

      // Call backend Gemini AI endpoint
      const aiResponse = await AIService.analyzeEvent(payload);

      if (!aiResponse || !aiResponse.requirements) {
        throw new Error('AI analysis completed but did not return valid requirements structure.');
      }

      // Cache the full result in window for potential task saving or summary display
      window.lastAiAnalysisResult = aiResponse;

      // The backend now returns validated, ready-to-save requirements
      return aiResponse.requirements;
    } catch (err) {
      console.error('AIRequirementGenerator failed:', err);
      throw err;
    }
  },

  /**
   * Generates full strategic planning package (requirements, tasks, risks)
   */
  async generateFullPlan(eventDetails) {
    return await AIService.analyzeEvent(eventDetails);
  }
};
